/* Lot 99: hsl() hue units, the reader colour (wf_cssprop_rgb24) and hsl() interpolation (generated by scripts/lot99_animgen.py; expectations from scripts/lot99_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the reader colour of v as #rrggbb, "-" when it is not one */
static const char *rg(const char *v) {
    unsigned int c = 0xdeadbeefu;
    int r = wf_cssprop_rgb24(v, (int)strlen(v), &c);
    if (!r) return c == 0xdeadbeefu ? "-" : "WRITTEN";
    if (r != 1 || c > 0xffffffu) return "BAD CODE";
    snprintf(g_o, sizeof(g_o), "#%06x", c);
    return g_o;
}

/* the interpolated text of two colours; the return code is checked */
static const char *ip(const char *a, const char *b, int t, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_interp(&g_p, a, b, t, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static void test_l99_color_0(void) {
    TEST_ASSERT_EQUAL_STRING("-", rg("hsl(120 50% 50 / 0.5)"));
    TEST_ASSERT_EQUAL_STRING("#fdfffd", rg("hsl(123.9464grad, 69.91%, 99.5%, 0.99995)"));
    TEST_ASSERT_EQUAL_STRING("#408000", rg("hsl(100grad 100% 25%)"));
    TEST_ASSERT_EQUAL_STRING("-", rg("hsl(tan, 2%, 3%)"));
    TEST_ASSERT_EQUAL_STRING("#ffffff", rg("hsla(11rad, 103%, 100%, 100%)"));
    TEST_ASSERT_EQUAL_STRING("#d8eeec", rg("hsl(-186.3316deg 39.8 89%)"));
    TEST_ASSERT_EQUAL_STRING("-", rg("#123456"));
    TEST_ASSERT_EQUAL_STRING("#000000", rg("HSL(7.2206RAD 0 0 / 1)"));
    TEST_ASSERT_EQUAL_STRING("#171c22", rg(" hsla(212 17.896% 11.2091%)"));
    TEST_ASSERT_EQUAL_STRING("-", rg("hs(1, 2%, 3%)"));
}

